package at.hausgarten.service;

import org.json.*;
import java.time.*;
import java.util.*;

/** Real owner/MCP/SQLite/PDF workflows with synthetic evidence in disposable QA contexts only. */
final class OfferDecisionNativeAcceptance {
    private static JSONObject request(String id)throws Exception{return SyntheticBusinessData.object().put("request_id",id);}
    private static JSONObject call(OwnerNativeAcceptance.Fixture fixture,String name,JSONObject args)throws Exception {
        JSONObject response=fixture.tools.rpc(new JSONObject().put("jsonrpc","2.0").put("id","qa_offer_decision_rpc").put("method","tools/call").put("params",new JSONObject().put("name",name).put("arguments",args))).getJSONObject("result"),body=response.getJSONObject("structuredContent");
        if(response.optBoolean("isError")){JSONObject error=body.getJSONObject("error");throw new PixelMcpWriteTools.Rejected(error.getString("code"),error.optString("message","QA offer tool rejected"));}return body.getJSONObject("data");
    }
    private static void rejected(String code,PixelMcpInstrumentation.Task task)throws Exception {try{task.run();}catch(PixelMcpWriteTools.Rejected expected){if(!expected.code.equals(code))throw expected;return;}throw new AssertionError("Expected "+code);}
    private static void setup(OwnerNativeAcceptance.Fixture f)throws Exception {
        JSONObject snapshot=f.store.getState().getJSONObject("master"),profile=SyntheticBusinessData.profile("minimal"),settings=profile.getJSONObject("business_settings");settings.put("invoice_issuer_confirmed","1").put("tax_mode","small_business").put("tax_exemption_text","QA synthetischer Befreiungshinweis");snapshot.put("business_settings",settings);JSONObject customer=snapshot.getJSONArray("customers").getJSONObject(0),template=profile.getJSONArray("customers").getJSONObject(0);for(String field:new String[]{"street","postal_code","city","country","email"})customer.put(field,template.get(field));f.store.commitSnapshot(snapshot,new HashSet<>());
    }
    private static JSONObject finalized(OwnerNativeAcceptance.Fixture f,String suffix)throws Exception {
        String day=LocalDate.now(ZoneId.of("Europe/Vienna")).toString();JSONObject draft=request("qa_offer_create_"+suffix).put("customer_id","qa_c").put("title","QA Angebot "+suffix).put("document_type","fixed_price").put("issue_date",day).put("valid_until",LocalDate.parse(day).plusDays(30).toString()).put("execution_window","QA geplanter Zeitraum").put("payment_terms","QA Zahlungsziel").put("customer_type","b2b").put("scope_confirmed",true).put("positions",new JSONArray().put(new JSONObject().put("title","QA Pflege").put("quantity",new java.math.BigDecimal("2.5")).put("price",52).put("unit","h").put("tax_rate",0).put("price_source","user_confirmed")));String id=call(f,"create_and_validate_offer",draft).getString("offer_id");JSONObject read=call(f,"get_offer",new JSONObject().put("offer_id",id));call(f,"finalize_offer",request("qa_offer_finalize_"+suffix).put("offer_id",id).put("expected_record_hash",read.getString("record_hash")).put("expected_context_hash",read.getString("context_hash")).put("confirmed",true));return call(f,"get_offer",new JSONObject().put("offer_id",id));
    }
    private static void localSyntheticCutover(OwnerNativeAcceptance.Fixture f)throws Exception {
        LocalAuthorityMigration migration=new LocalAuthorityMigration(f.context,f.store);JSONObject preview=migration.preview();String now=Instant.now().toString();JSONObject backup=new JSONObject().put("formatVersion",1).put("verified",true).put("external_verified",true).put("backup_id","qa_synthetic_offer_evidence").put("archive_sha256","a".repeat(64)).put("business_snapshot_sha256",preview.getString("state_sha256")).put("captured_at",now).put("verified_at",now),writers=new JSONObject().put("formatVersion",1).put("external_writers_disabled",true).put("evidence_sha256","b".repeat(64)).put("evidence_reference","qa_isolated_synthetic_evidence_port_only").put("checked_at",now);migration.activate("qa_offer_local_migration",preview.getString("preview_hash"),backup,writers);
    }
    static void run(PixelMcpInstrumentation test)throws Exception {
        test.probe("offer decision native local acceptance binds exact original PDF and repeated conversion creates one order after SQLite reopen",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            setup(f);JSONObject read=finalized(f,"accepted"),offer=read.getJSONObject("offer");String id=offer.getString("id"),pdf=offer.getString("pdf_sha256");localSyntheticCutover(f);JSONObject missing=call(f,"get_offer",new JSONObject().put("offer_id",id));rejected("OFFER_ACCEPTANCE_EVIDENCE_REQUIRED",()->call(f,"convert_offer_to_order",request("qa_offer_convert_without_acceptance").put("offer_id",id).put("expected_record_hash",missing.getString("record_hash")).put("confirmed",true)));
            JSONObject acceptance=request("qa_offer_acceptance").put("offer_id",id).put("expected_record_hash",missing.getString("record_hash")).put("accepted_at",Instant.now().toString()).put("evidence","QA bestätigte Annahme dieses finalen PDFs");test.yes(call(f,"record_offer_acceptance",acceptance).getJSONObject("decision").getString("decision").equals("accepted")&&call(f,"record_offer_acceptance",acceptance).getBoolean("replayed"));test.yes(call(f,"get_offer_decision_history",new JSONObject().put("offer_id",id)).getInt("total")==1);RevierApplicationService boundary=new RevierApplicationService(new RevierSnapshotRepository(f.store.getReadableDatabase(),PixelMcpReadTools.effective(f.store.getState())));test.yes(boundary.validateRelationships().getJSONObject("offer_decisions").getInt("decisions")==1);String receiptKey=OfferDecisionRules.PREFIX+"request:"+PixelMcpWriteTools.hash("qa_offer_acceptance"),receipt=f.store.ownerValue(receiptKey,"");JSONObject malformed=new JSONObject(receipt);malformed.getJSONObject("result").put("offer_id","qa_wrong_offer");f.store.putOwnerValue(receiptKey,malformed.toString());rejected("OFFER_DECISION_RELATION_INVALID",()->boundary.validateRelationships());f.store.putOwnerValue(receiptKey,receipt);test.yes(boundary.validateRelationships().getString("status").equals("PASS"));
            JSONObject after=call(f,"get_offer",new JSONObject().put("offer_id",id));test.yes(after.getJSONObject("decision").getString("decision").equals("accepted")&&after.getJSONObject("offer").getString("status").equals("finalized")&&after.getJSONObject("offer").getString("pdf_sha256").equals(pdf));JSONObject converted=call(f,"convert_offer_to_order",request("qa_offer_convert_accepted").put("offer_id",id).put("expected_record_hash",after.getString("record_hash")).put("confirmed",true));String order=converted.getString("order_id");test.yes(!order.isEmpty()&&!converted.getBoolean("invoice_created"));
            JSONObject current=call(f,"get_offer",new JSONObject().put("offer_id",id));test.yes(call(f,"convert_offer_to_order",request("qa_offer_convert_repeated").put("offer_id",id).put("expected_record_hash",current.getString("record_hash")).put("confirmed",true)).getString("order_id").equals(order));test.yes(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("orders").length()==1&&PixelMcpReadTools.effective(f.store.getState()).getJSONArray("invoices").length()==0);new BusinessDocumentStore(f.context).read(current.getJSONObject("offer"));
            JSONObject start=request("qa_converted_order_start").put("customer_id","qa_c").put("order_id",order).put("work_date",LocalDate.now(ZoneId.of("Europe/Vienna")).toString()).put("activity","QA Arbeit am bestätigten Angebotsauftrag"),session=f.store.startWorkSession(new JSONObject(start.toString()));test.yes(session.getString("order_id").equals(order)&&session.getString("billing_customer_id").equals("qa_c")&&f.store.startWorkSession(new JSONObject(start.toString())).getString("id").equals(session.getString("id")));test.yes(!start.has("billing_customer_id")&&!start.has("_request_input_hash"));rejected("REPLAY_MISMATCH",()->f.store.startWorkSession(new JSONObject(start.toString()).put("activity","QA andere Startangaben")));test.yes(f.store.workSessions().current().getString("id").equals(session.getString("id")));
            JSONObject work=new JSONObject().put("id","qa_converted_order_manual_work").put("customer_id","qa_c").put("order_id",order).put("work_date",LocalDate.now(ZoneId.of("Europe/Vienna")).toString()).put("activity","QA eigenständiger Nachtrag zum angenommenen Auftrag").put("hours",1.25);test.yes(f.store.saveEditorRecord("worklog",new JSONObject(work.toString()).put("_request_id","qa_converted_order_work_commit")).equals(work.getString("id")));test.yes(PixelMcpWriteTools.find(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("worklogs"),work.getString("id")).getString("order_id").equals(order));
            android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();test.yes(image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes));image.recycle();JSONObject photo=new JSONObject().put("id","qa_converted_order_photo").put("_photo_request_id","qa_converted_order_photo_commit").put("customer_id","qa_c").put("order_id",order).put("worklog_id",work.getString("id")).put("original_name","qa_converted_order.png").put("data","data:image/png;base64,"+android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP));test.yes(f.store.savePhoto(new JSONObject(photo.toString())).equals(photo.getString("id"))&&f.store.savePhoto(new JSONObject(photo.toString())).equals(photo.getString("id")));test.yes(PixelMcpWriteTools.find(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("photos"),photo.getString("id")).getString("order_id").equals(order));
            BusinessDataBridge bridge=new BusinessDataBridge(f.context,f.store,null,()->{});String pendingBefore=PixelMcpWriteTools.hash(f.store.pendingActions());JSONObject summary=new JSONObject(bridge.ownerCall("get_business_summary","{}"));test.yes(summary.getBoolean("ok")&&summary.getJSONObject("data").getInt("work_records")==2&&summary.getJSONObject("data").getJSONArray("billing_groups").getJSONObject(0).getJSONArray("work_records").length()==2);test.yes(!new JSONObject(bridge.ownerCall("qa_unregistered_reader","{}")).optBoolean("ok")&&!new JSONObject(bridge.ownerCall("get_business_summary","{\"qa_unknown\":true}")).optBoolean("ok")&&pendingBefore.equals(PixelMcpWriteTools.hash(f.store.pendingActions())));
            f.store.close();try(PixelLocalStore reopened=new PixelLocalStore(f.context)){JSONObject history=new OfferDecisionService(new LocalOwnerRepository(f.context,reopened)).query("get_offer_decision_history",new JSONObject().put("offer_id",id));test.yes(history.getString("decision_status").equals("accepted")&&history.getInt("total")==1);}
        }});
        test.probe("offer decision native decline remains immutable and revision starts undecided without order or invoice",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            setup(f);JSONObject read=finalized(f,"declined"),offer=read.getJSONObject("offer");String id=offer.getString("id"),pdf=offer.getString("pdf_sha256");localSyntheticCutover(f);read=call(f,"get_offer",new JSONObject().put("offer_id",id));JSONObject decline=request("qa_offer_decline").put("offer_id",id).put("expected_record_hash",read.getString("record_hash")).put("reason","QA nicht angenommen");test.yes(call(f,"decline_offer",decline).getJSONObject("decision").getString("decision").equals("declined")&&call(f,"decline_offer",decline).getBoolean("replayed"));JSONObject declined=call(f,"get_offer",new JSONObject().put("offer_id",id));rejected("OFFER_DECLINED",()->call(f,"convert_offer_to_order",request("qa_offer_convert_declined").put("offer_id",id).put("expected_record_hash",declined.getString("record_hash")).put("confirmed",true)));test.yes(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("orders").length()==0&&PixelMcpReadTools.effective(f.store.getState()).getJSONArray("invoices").length()==0&&declined.getJSONObject("offer").getString("pdf_sha256").equals(pdf));
            String revision=call(f,"duplicate_offer",request("qa_offer_revision").put("offer_id",id)).getString("offer_id");test.yes(call(f,"get_offer_decision_history",new JSONObject().put("offer_id",revision)).getString("decision_status").equals("not_recorded"));test.yes(call(f,"get_offer_decision_history",new JSONObject().put("offer_id",revision)).getJSONObject("revision").getString("parent_offer_id").equals(id));test.yes(call(f,"get_offer_decision_history",new JSONObject().put("offer_id",id)).getInt("total")==1);new BusinessDocumentStore(f.context).read(declined.getJSONObject("offer"));
        }});
    }
}
